// Intelligence notes: object type never implies importance or urgency. Importance and deadline are independent signals; a deadline only reduces how long waiting remains possible. A wish may matter, a needed purchase may wait, and current energy belongs to user context rather than any object. Only collect context that can later be used deliberately.
function recommendationProfile(i){if(i.blocker?.enabled&&(!i.blocker.availableFrom||i.blocker.availableFrom>todayKey()))return{eligible:false,score:-999,route:'blocked',reason:'Wacht nog op iets anders.'};const capacity=checkin.date===todayKey()?Number(checkin.energy)||3:3,necessity=i.necessity??null,impact=i.impact??null,load=i.load??null,resistance=Number(i.resistance)||3,age=Math.max(0,(Date.now()-(i.createdAt||Date.now()))/864e5),skips=(i.recommendationHistory?.skips||[]).length+Number(i.postponeCount||0);let deadlineBoost=0,deadlineText='';if(i.deadline?.enabled&&i.deadline.date){const d=(new Date(i.deadline.date+'T12:00')-new Date(todayKey()+'T12:00'))/864e5;deadlineBoost=d<=0?14:d<=3?10:d<=7?6:2;deadlineText=d<=3?'Moet binnenkort gebeuren.':''}let fit=0;if(load)fit=load<=Math.max(1,capacity-1)?5:load<=capacity?2:-3;if(i.durationExplicit&&i.duration)fit+=i.duration<=15?3:i.duration<=45?1:i.duration>90&&capacity<=2?-3:0;/* Weerstand is startfrictie; belasting bepaalt of uitvoering nu past. */const antiAvoid=Math.min(6,age/14+skips*1.3);const score=deadlineBoost+(necessity||0)*4+(impact||0)*2.5+fit+(5-resistance)*.8+antiAvoid;let route='fit';if(i.durationExplicit&&i.duration<=15&&(load??2)<=2)route='small';else if((load??2)>=3||resistance>=4)route='stretch';const reason=deadlineText||(route==='small'?'Klein om te beginnen en past waarschijnlijk nu.':route==='stretch'?(impact>=3?'Vraagt wat meer, maar levert veel op.':'Bewust een iets pittigere optie.'):(impact>=3?'Past redelijk bij wat je nu aankunt en levert veel op.':i.durationExplicit?`Past bij wat je nu aankunt en duurt ongeveer ${i.duration} minuten.`:'Past redelijk bij wat je nu aankunt.'));return{eligible:true,score,route,reason}}
