$('addSublistButton').onclick=()=>{const l=lists.find(x=>x.id===currentListId);if(l)openSublist(l)};$('saveSublistButton').onclick=()=>{const l=lists.find(x=>x.id===currentListId);if(!l||!requireField($('sublistName')))return;const clean=$('sublistName').value.trim();l.sublistColors=l.sublistColors||{};if(editingSublistName){l.sublists=l.sublists.map(s=>s===editingSublistName?clean:s);l.items.forEach(i=>{if(i.sublist===editingSublistName)i.sublist=clean});delete l.sublistColors[editingSublistName]}else if(!l.sublists.includes(clean))l.sublists.push(clean);if(selectedSublistColor)l.sublistColors[clean]=selectedSublistColor;editingSublistName=null;saveLists();close('sublistOverlay');renderListDetail()};$('sublistName').onkeydown=e=>{if(e.key==='Enter')$('saveSublistButton').click()};$('listBackButton').onclick=()=>showScreen('lists');$('editListButton').onclick=()=>{const l=lists.find(x=>x.id===currentListId);menu([{label:'Bewerken',run:()=>openList(l)},{label:'Verwijderen',danger:true,run:()=>removeWithUndo(lists,l,saveLists,()=>showScreen('lists'),'Weet je zeker dat je dit lijstje wilt verwijderen?','Lijstje verwijderd')}])};

function renderIdeas(){const box=$('ideasList');box.innerHTML='';ideas.sort((a,b)=>a.order-b.order).forEach(i=>{const row=document.createElement('div');row.className='idea-card';row.dataset.id=i.id;row.draggable=true;const t=document.createElement('p');t.textContent=i.text;row.append(t,moreButton(()=>ideaMenu(i)));wireDrag(row,'ideas');box.append(row)});if(!ideas.length){const e=empty(box,'Nog geen ideeën. Tik om er een te bewaren.');e.classList.add('clickable-empty');e.onclick=()=>openIdea()}}
function openIdea(i=null){editingIdeaId=i?.id||null;$('ideaModalTitle').textContent=i?'Idee bewerken':'Idee bewaren';$('ideaText').value=i?.text||'';open('ideaOverlay')}
