function ideaMenu(i){menu([{label:'Bewerken',run:()=>openIdea(i)},{label:'Omzetten naar taak',run:()=>{openAction(null);$('actionTitle').value=i.text;removeIdea(i)}},{label:'Omzetten naar project',run:()=>{openProject();$('projectName').value=i.text;removeIdea(i)}},{label:'Omzetten naar aankoop',run:()=>{openWishlist();$('wishlistName').value=i.text;removeIdea(i) }},{label:'Verwijderen',danger:true,run:()=>removeWithUndo(ideas,i,saveIdeas)}])}
