function renderInbox(){const box=$('inboxList');box.innerHTML='';inbox.slice().sort((a,b)=>a.order-b.order||a.createdAt-b.createdAt).forEach(i=>{const row=document.createElement('div');row.className='inbox-row';const text=document.createElement('p');text.textContent=i.text;row.append(text,moreButton(()=>inboxMenu(i)));box.append(row)});if(!inbox.length)empty(box,'Nog niets om uit te zoeken.','Alles heeft een plek.')}
function removeInboxItem(id){const index=inbox.findIndex(i=>i.id===id);if(index<0)return;inbox.splice(index,1);inbox.forEach((i,n)=>i.order=n);saveInbox()}
function finishInboxConversion(){if(!pendingInboxConversionId)return;removeInboxItem(pendingInboxConversionId);pendingInboxConversionId=null;if(currentScreen==='inbox')renderInbox()}
function beginInboxConversion(item,type){pendingInboxConversionId=item.id;if(type==='task'){openAction();$('actionTitle').value=item.text}else if(type==='project'){openProject();$('projectName').value=item.text}else if(type==='wishlist'){openWishlist();$('wishlistName').value=item.text}else if(type==='list'){openList();$('listName').value=item.text}}
function inboxMenu(item){menu([{label:'Taak maken',run:()=>beginInboxConversion(item,'task')},{label:'Project maken',run:()=>beginInboxConversion(item,'project')},{label:'Idee maken',run:()=>{ideas.push({id:uid(),text:item.text,order:ideas.length,createdAt:Date.now()});saveIdeas();removeInboxItem(item.id);renderInbox()}},{label:'Aankoop maken',run:()=>beginInboxConversion(item,'wishlist')},{label:'Lijstje maken',run:()=>beginInboxConversion(item,'list')},{label:'Verwijderen',danger:true,run:()=>removeWithUndo(inbox,item,saveInbox,renderInbox)}])}
