function wireDrag(el,scope,handle=el){let startX=0,startY=0,targetId='',active=false,justDragged=false;el.classList.add('draggable-item');const blocked=e=>e.target.closest('.check,.more-button,.column-menu,input,a');const begin=e=>{if(blocked(e))return false;startX=e.clientX;startY=e.clientY;targetId='';active=false;return true};const move=e=>{if(!active&&Math.hypot(e.clientX-startX,e.clientY-startY)>7){active=true;drag={id:el.dataset.id,scope};el.classList.add('dragging');navigator.vibrate?.(18)}if(!active)return;e.preventDefault();const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-id]');if(target?.dataset.id&&target.dataset.id!==el.dataset.id)targetId=target.dataset.id};const end=()=>{if(active){justDragged=true;if(targetId)reorder(scope,el.dataset.id,targetId);setTimeout(()=>justDragged=false,0)}active=false;drag=null;targetId='';el.classList.remove('dragging')};el.addEventListener('click',e=>{if(justDragged){e.preventDefault();e.stopImmediatePropagation()}},true);handle.onpointerdown=e=>{if(e.pointerType==='mouse'||!begin(e))return;handle.setPointerCapture?.(e.pointerId)};handle.onpointermove=e=>{if(e.pointerType==='mouse')return;move(e)};handle.onpointerup=e=>{if(e.pointerType==='mouse')return;end();handle.releasePointerCapture?.(e.pointerId)};handle.onpointercancel=end;handle.onmousedown=e=>{if(!begin(e))return;const mouseMove=event=>move(event),mouseUp=()=>{document.removeEventListener('mousemove',mouseMove);document.removeEventListener('mouseup',mouseUp);end()};document.addEventListener('mousemove',mouseMove);document.addEventListener('mouseup',mouseUp)}}
function reorderItems(arr,from,to,onMove){const a=arr.findIndex(x=>x.id===from),b=arr.findIndex(x=>x.id===to);if(a<0||b<0||a===b)return false;const target=arr[b],[m]=arr.splice(a,1);onMove?.(m,target);arr.splice(Math.min(b,arr.length),0,m);arr.forEach((x,n)=>x.order=n);return true}
function reorder(scope,from,to){let arr;if(scope==='actions')arr=actions.filter(i=>!i.done).sort((a,b)=>a.order-b.order);else if(scope==='projects')arr=projects.filter(p=>!p.archived).sort((a,b)=>a.order-b.order);else if(scope==='wishlist')arr=wishlist.filter(i=>i.bought===(wishlistFilter==='bought')&&(wishlistFilter==='bought'||purchaseFilter==='all'||i.purchaseType===purchaseFilter)).sort((a,b)=>a.order-b.order);else if(scope==='ideas')arr=ideas.slice().sort((a,b)=>a.order-b.order);else if(scope.startsWith('project:'))arr=actions.filter(i=>i.projectId===scope.slice(8)&&!i.done).sort((a,b)=>a.order-b.order);else if(scope.startsWith('list:'))arr=lists.find(l=>l.id===scope.slice(5)).items.slice().sort((a,b)=>a.order-b.order);if(!arr||!reorderItems(arr,from,to,scope.startsWith('list:')?(m,target)=>m.sublist=target?.sublist||m.sublist:null))return;drag=null;if(scope==='projects')saveProjects();else if(scope==='wishlist')saveWishlist();else if(scope==='ideas')saveIdeas();else if(scope.startsWith('list:'))saveLists();else saveActions();refresh();if(scope.startsWith('list:'))renderListDetail()}
