const LUMI_PALETTE=['cyan','violet','rose','gold'];
function createLumi({mode='action',x=50,y=null}={}){const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;if(mode==='ambient'&&reduced)return null;const effect=document.createElement('i'),tone=LUMI_PALETTE[Math.floor(Math.random()*LUMI_PALETTE.length)];effect.className=`lumi lumi--${mode} lumi--${tone}`;effect.setAttribute('aria-hidden','true');effect.style.setProperty('--lumi-x',x+(typeof x==='number'?'vw':''));if(y!==null)effect.style.setProperty('--lumi-y',y+(typeof y==='number'?'vh':''));const direction=Math.random()>.5?1:-1,drift=direction*(18+Math.round(Math.random()*18));effect.style.setProperty('--lumi-drift-x',`${drift}px`);effect.style.setProperty('--lumi-drift-y',`${mode==='ambient'?-(34+Math.round(Math.random()*28)):-(58+Math.round(Math.random()*24))}px`);if(mode==='action'){const rise=Math.round(innerHeight*(.32+Math.random()*.03)),bend=direction*(20+Math.round(Math.random()*12));effect.style.offsetPath=`path("M 0 0 C ${-bend*.45} ${-rise*.28}, ${bend*1.05} ${-rise*.7}, ${bend} ${-rise}")`}document.body.append(effect);effect.addEventListener('animationend',()=>effect.remove(),{once:true});setTimeout(()=>effect.remove(),mode==='ambient'?8000:3000);return effect}
