function renderFinance(){const box=$('financeList');box.innerHTML='';const items=financeItems.filter(item=>financeFilter==='done'?item.status==='done':item.status!=='done').sort((a,b)=>a.order-b.order);if(!items.length)return empty(box,financeFilter==='done'?'Nog niets afgehandeld':'Geen financiële losse eindjes','Voeg iets toe',()=>openFinance());items.forEach(item=>{const row=document.createElement('article');row.className='vault-item finance-item';const remaining=Math.max(0,item.amount-item.paid);row.innerHTML=`<div><strong></strong><small></small></div>`;row.querySelector('strong').textContent=item.title;row.querySelector('small').textContent=`${item.direction==='receive'?'Te ontvangen':'Te betalen'} · ${formatPrice(item.status==='partial'?remaining:item.amount)}${item.party?' · '+item.party:''}`;row.append(moreButton(()=>menu([{label:'Bewerken',run:()=>openFinance(item)},{label:'Verwijderen',danger:true,run:()=>removeWithUndo(financeItems,item,saveFinance,renderFinance)}])));box.append(row)})}
function openFinance(item=null){editingFinanceId=item?.id||null;financeDirection=item?.direction||'receive';$('financeModalTitle').textContent=item?'Financieel item bewerken':'Nieuw financieel item';$('financeTitle').value=item?.title||'';$('financeAmount').value=item?.amount||'';$('financeParty').value=item?.party||'';$('financeDate').value=item?.date||'';$('financeDueDate').value=item?.dueDate||'';$('financeStatus').value=item?.status||'open';$('financePaid').value=item?.paid||'';$('financeNote').value=item?.note||'';document.querySelectorAll('[data-finance-direction]').forEach(button=>button.classList.toggle('selected',button.dataset.financeDirection===financeDirection));syncFinancePartial();open('financeOverlay')}
