$('financeForm').onsubmit=event=>{event.preventDefault();if(!requireField($('financeTitle'))||!requireField($('financeAmount')))return;const amount=Number($('financeAmount').value.replace(',','.'));if(!Number.isFinite(amount)||amount<=0)return;const data={title:$('financeTitle').value.trim(),amount,direction:financeDirection,party:$('financeParty').value.trim(),date:$('financeDate').value,dueDate:$('financeDueDate').value,status:$('financeStatus').value,paid:$('financeStatus').value==='partial'?Math.min(amount,Number($('financePaid').value.replace(',','.'))||0):$('financeStatus').value==='done'?amount:0,note:$('financeNote').value.trim()};const existing=financeItems.find(item=>item.id===editingFinanceId);if(existing)Object.assign(existing,data);else financeItems.push({id:uid(),...data,order:financeItems.length,createdAt:Date.now()});saveFinance();close('financeOverlay');renderFinance();lumiSuccess()};document.querySelectorAll('.finance-tab').forEach(button=>button.onclick=()=>{financeFilter=button.dataset.financeFilter;document.querySelectorAll('.finance-tab').forEach(other=>other.classList.toggle('active',other===button));renderFinance()});

let editingDocumentId=null,pendingDocumentFile=null;
function renderDocuments(){const box=$('documentsList'),query=$('documentSearch').value.trim().toLowerCase();box.innerHTML='';const items=documents.filter(item=>[item.title,item.category,...item.tags].join(' ').toLowerCase().includes(query)).sort((a,b)=>a.order-b.order);if(!items.length)return empty(box,query?'Geen documenten gevonden':'Nog geen documenten',query?'Zoek op een andere term':'Voeg een document of foto toe',query?null:()=>openDocument());items.forEach(item=>{const row=document.createElement('article');row.className='vault-item document-item';row.innerHTML='<div><strong></strong><small></small></div>';row.querySelector('strong').textContent=item.title;row.querySelector('small').textContent=[item.category,item.fileName,item.tags.join(', ')].filter(Boolean).join(' · ');if(item.fileData){const openFile=document.createElement('a');openFile.className='document-open';openFile.textContent='Open';openFile.href=item.fileData;openFile.target='_blank';openFile.rel='noopener';row.append(openFile)}row.append(moreButton(()=>menu([{label:'Bewerken',run:()=>openDocument(item)},{label:'Verwijderen',danger:true,run:()=>removeWithUndo(documents,item,saveDocuments,renderDocuments)}])));box.append(row)})}
function openDocument(item=null){editingDocumentId=item?.id||null;pendingDocumentFile=null;$('documentModalTitle').textContent=item?'Document bewerken':'Nieuw document';$('documentTitle').value=item?.title||'';$('documentFile').value='';$('documentFileStatus').textContent=item?.fileName?`Bewaard: ${item.fileName}`:'';$('documentCategory').value=item?.category||'';$('documentDate').value=item?.date||'';$('documentParty').value=item?.party||'';$('documentAmount').value=item?.amount||'';$('documentTags').value=(item?.tags||[]).join(', ');$('documentNote').value=item?.note||'';open('documentOverlay')}
$('documentFile').onchange=()=>{const file=$('documentFile').files[0];if(!file)return;if(file.size>2*1024*1024){$('documentFileStatus').textContent='Kies een bestand kleiner dan 2 MB.';$('documentFile').value='';return}const reader=new FileReader();reader.onload=()=>{pendingDocumentFile={fileName:file.name,fileType:file.type,fileData:reader.result};$('documentFileStatus').textContent=`Toegevoegd: ${file.name}`};reader.readAsDataURL(file)};
$('documentForm').onsubmit=event=>{event.preventDefault();if(!requireField($('documentTitle')))return;const existing=documents.find(item=>item.id===editingDocumentId);if(!existing&&!pendingDocumentFile){$('documentFileStatus').textContent='Voeg een document of foto toe.';return}const rawAmount=$('documentAmount').value.trim().replace(',','.'),data={title:$('documentTitle').value.trim(),category:$('documentCategory').value.trim(),date:$('documentDate').value,party:$('documentParty').value.trim(),amount:rawAmount&&Number.isFinite(Number(rawAmount))?Number(rawAmount):'',tags:$('documentTags').value.split(',').map(tag=>tag.trim()).filter(Boolean),note:$('documentNote').value.trim(),...(pendingDocumentFile||{})};if(existing)Object.assign(existing,data);else documents.push({id:uid(),...data,order:documents.length,createdAt:Date.now()});saveDocuments();close('documentOverlay');renderDocuments();lumiSuccess()};$('documentSearch').oninput=renderDocuments;

