function financeItemRow(item){const row=document.createElement('article'),remaining=Math.max(0,item.amount-item.paid);row.className='vault-item finance-item';row.innerHTML='<div><strong></strong><small></small></div>';row.querySelector('strong').textContent=item.title;row.querySelector('small').textContent=`${item.direction==='receive'?'Te ontvangen':'Te betalen'} · ${formatPrice(item.status==='partial'?remaining:item.amount)}${item.date?' · '+formatDate(item.date):''}`;row.append(moreButton(()=>menu([{label:'Bewerken',run:()=>openFinance(item)},{label:'Verwijderen',danger:true,run:()=>removeWithUndo(financeItems,item,saveFinance,renderFinance)}])));return row}
renderFinance=function(){const box=$('financeList');box.innerHTML='';const items=financeItems.filter(item=>financeFilter==='done'?item.status==='done':item.status!=='done').sort((a,b)=>a.order-b.order);if(!items.length)return empty(box,financeFilter==='done'?'Nog niets afgehandeld':'Geen financiële losse eindjes','Voeg iets toe',()=>openFinance());const grouped=new Map(),ungrouped=[];items.forEach(item=>{const party=item.party?.trim();if(!party)return ungrouped.push(item);if(!grouped.has(party))grouped.set(party,[]);grouped.get(party).push(item)});grouped.forEach((entries,party)=>{const details=document.createElement('details');details.className='finance-group';const total=entries.reduce((sum,item)=>sum+Math.max(0,item.amount-item.paid),0),summary=document.createElement('summary');summary.innerHTML='<span><strong></strong><small></small></span><i class="ph ph-caret-down" aria-hidden="true"></i>';summary.querySelector('strong').textContent=party;summary.querySelector('small').textContent=`${formatPrice(total)} ${entries.every(item=>item.direction==='receive')?'te ontvangen':entries.every(item=>item.direction==='pay')?'te betalen':'openstaand'} · ${entries.length} ${entries.length===1?'item':'items'}`;details.append(summary);const list=document.createElement('div');list.className='finance-group-items';entries.forEach(item=>list.append(financeItemRow(item)));details.append(list);box.append(details)});ungrouped.forEach(item=>box.append(financeItemRow(item)))};

